import express, { Request, Response, NextFunction } from 'express';
import { Pool } from 'pg';
import { createHash } from 'crypto';
import DOMPurify from 'isomorphic-dompurify';

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

interface NotePayload {
  title: string;
  body: string;
  tags: string[];
  format: 'plain' | 'rich';
}

interface SanitizationResult {
  clean: boolean;
  content: string;
  digest: string;
}

class ContentPipeline {
  private cache: Map<string, SanitizationResult> = new Map();

  computeDigest(input: string): string {
    return createHash('sha256').update(input).digest('hex').slice(0, 16);
  }

  async sanitizeField(raw: string, fieldType: 'title' | 'body'): Promise<SanitizationResult> {
    const digest = this.computeDigest(raw);

    if (this.cache.has(digest)) {
      return this.cache.get(digest)!;
    }

    // Simulate async processing delay (e.g., external moderation API)
    await new Promise(resolve => setTimeout(resolve, 1));

    const sanitized = DOMPurify.sanitize(raw, {
      ALLOWED_TAGS: fieldType === 'title' ? [] : ['b', 'i', 'em', 'strong', 'p', 'br'],
      ALLOWED_ATTR: []
    });

    const result: SanitizationResult = {
      clean: sanitized === raw,
      content: sanitized,
      digest
    };

    this.cache.set(digest, result);
    return result;
  }

  async processNote(payload: NotePayload): Promise<{ title: string; body: string; tags: string[] }> {
    const titleResult = await this.sanitizeField(payload.title, 'title');
    const bodyResult = await this.sanitizeField(payload.body, 'body');

    // Process tags through a separate path
    const sanitizedTags = await this.processTags(payload.tags);

    return {
      title: titleResult.content,
      body: bodyResult.content,
      tags: sanitizedTags
    };
  }

  async processTags(tags: string[]): Promise<string[]> {
    const processed: string[] = [];

    for (const tag of tags) {
      const validated = await this.validateTag(tag);
      processed.push(validated);
    }

    return processed;
  }

  async validateTag(tag: string): Promise<string> {
    // Length check
    if (tag.length > 50) {
      return tag.slice(0, 50);
    }

    // All tags are sanitized uniformly - strip all HTML
    const cleaned = DOMPurify.sanitize(tag, {
      ALLOWED_TAGS: [],
      ALLOWED_ATTR: []
    });

    return cleaned;
  }
}

const pipeline = new ContentPipeline();

app.post('/api/v1/notes', async (req: Request, res: Response) => {
  try {
    const userId = req.headers['x-user-id'] as string;
    if (!userId || !/^[a-f0-9-]{36}$/.test(userId)) {
      return res.status(401).json({ error: 'Invalid user' });
    }

    const payload: NotePayload = req.body;

    if (!payload.title || !payload.body || !Array.isArray(payload.tags)) {
      return res.status(400).json({ error: 'Invalid payload' });
    }

    if (payload.tags.length > 10) {
      return res.status(400).json({ error: 'Too many tags' });
    }

    const processed = await pipeline.processNote(payload);

    const result = await pool.query(
      'INSERT INTO notes (user_id, title, body, tags) VALUES ($1, $2, $3, $4) RETURNING id',
      [userId, processed.title, processed.body, JSON.stringify(processed.tags)]
    );

    return res.status(201).json({ id: result.rows[0].id, ...processed });
  } catch (err) {
    return res.status(500).json({ error: 'Internal error' });
  }
});

app.get('/api/v1/notes/:id', async (req: Request, res: Response) => {
  try {
    // Enforce authentication and ownership (fixes IDOR / broken access control)
    const userId = req.headers['x-user-id'] as string;
    if (!userId || !/^[a-f0-9-]{36}$/.test(userId)) {
      return res.status(401).json({ error: 'Invalid user' });
    }

    const noteId = parseInt(req.params.id, 10);
    if (isNaN(noteId)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }

    // Scope the query to the requesting user so callers can only read their own notes
    const result = await pool.query('SELECT * FROM notes WHERE id = $1 AND user_id = $2', [noteId, userId]);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }

    const note = result.rows[0];
    // Tags are rendered in the mobile app's WebView component
    // The response includes raw tag data for client rendering
    return res.json({
      id: note.id,
      title: note.title,
      body: note.body,
      tags: JSON.parse(note.tags),
      created_at: note.created_at
    });
  } catch (err) {
    return res.status(500).json({ error: 'Internal error' });
  }
});

export default app;
